-- =====================================================
-- Database portofolio akademik (MySQL 8 / MariaDB 10.4+)
-- Updated: 2026-10-26T15:52:40.908Z
-- =====================================================
CREATE DATABASE IF NOT EXISTS `defaultdb`
  CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `defaultdb`;

SET NAMES utf8mb4;

-- 1. Penelitian & Pengabdian (P2M)
CREATE TABLE IF NOT EXISTS p2m_activities (
  id          INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  year        SMALLINT UNSIGNED NOT NULL,
  role        ENUM('Ketua','Anggota') NOT NULL,
  title       TEXT NOT NULL,
  status      VARCHAR(30) NOT NULL,
  jenis       ENUM('Penelitian','Pengabdian') NOT NULL,
  group_riset VARCHAR(150),
  skema       VARCHAR(255),
  INDEX idx_year (year),
  INDEX idx_jenis (jenis)
) ENGINE=InnoDB;

-- 2. Publikasi Scopus
CREATE TABLE IF NOT EXISTS scopus_publications (
  id        INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  year      SMALLINT UNSIGNED NOT NULL,
  title     TEXT NOT NULL,
  journal   VARCHAR(300),
  publisher VARCHAR(300),
  link      VARCHAR(500),
  doi       VARCHAR(150),
  authors   TEXT,
  INDEX idx_year (year)
) ENGINE=InnoDB;

-- 3. Jurnal
CREATE TABLE IF NOT EXISTS journals (
  id        INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  year      SMALLINT UNSIGNED NOT NULL,
  title     TEXT NOT NULL,
  journal   VARCHAR(300),
  publisher VARCHAR(300),
  link      VARCHAR(500),
  authors   TEXT,
  INDEX idx_year (year)
) ENGINE=InnoDB;

-- 4. Prosiding
CREATE TABLE IF NOT EXISTS proceedings (
  id            INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  year          SMALLINT UNSIGNED NOT NULL,
  title         TEXT NOT NULL,
  publisher     VARCHAR(300),
  link          VARCHAR(500),
  seminar_name  VARCHAR(300),
  seminar_theme TEXT,
  authors       TEXT,
  INDEX idx_year (year)
) ENGINE=InnoDB;

-- 5. Buku
CREATE TABLE IF NOT EXISTS books (
  id        INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  year      SMALLINT UNSIGNED NOT NULL,
  title     TEXT NOT NULL,
  publisher VARCHAR(200),
  isbn      VARCHAR(30),
  authors   TEXT,
  INDEX idx_year (year)
) ENGINE=InnoDB;

-- 6. Paten & HKI
CREATE TABLE IF NOT EXISTS patents_hki (
  id          INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  year        SMALLINT UNSIGNED NOT NULL,
  title       TEXT NOT NULL,
  jenis       ENUM('Paten','Hak Cipta') NOT NULL,
  nomor       VARCHAR(50),
  inventors   TEXT,
  anggota_tim TEXT,
  INDEX idx_year (year)
) ENGINE=InnoDB;

-- 7. Dokumen Skripsi & Tesis Digilib UNS
CREATE TABLE IF NOT EXISTS digilib_documents (
  doc_id          INT UNSIGNED PRIMARY KEY,
  penulis_utama   VARCHAR(200) NOT NULL,
  penulis_tambahan TEXT,
  nim_nip         VARCHAR(30),
  tahun           SMALLINT UNSIGNED NOT NULL,
  judul           TEXT NOT NULL,
  edisi           VARCHAR(100),
  imprint         VARCHAR(200),
  program_studi   VARCHAR(100),
  kolasi          VARCHAR(100),
  sumber          VARCHAR(200),
  kata_kunci      TEXT,
  jenis_dokumen   VARCHAR(50),
  issn            VARCHAR(30),
  isbn            VARCHAR(30),
  link_doi_jurnal VARCHAR(500),
  status          VARCHAR(30),
  pembimbing      TEXT,
  penguji         TEXT,
  catatan_umum    TEXT,
  fakultas        VARCHAR(100),
  operator        VARCHAR(100),
  asal            VARCHAR(100),
  detail_url      VARCHAR(600),
  photo_url       VARCHAR(500),
  photo_base64    LONGTEXT,
  infographic     LONGTEXT,
  has_infographic TINYINT(1) DEFAULT 0,
  INDEX idx_tahun (tahun),
  INDEX idx_penulis (penulis_utama)
) ENGINE=InnoDB;

-- 8. Perkuliahan (Teaching Courses)
CREATE TABLE IF NOT EXISTS teaching_courses (
  id VARCHAR(64) PRIMARY KEY,
  code VARCHAR(30) NOT NULL,
  name VARCHAR(200) NOT NULL,
  level VARCHAR(50) NOT NULL,
  program VARCHAR(150) NOT NULL,
  academic_year VARCHAR(30) NOT NULL,
  semester VARCHAR(30) NOT NULL,
  description TEXT,
  learning_outcomes TEXT,
  materials_url VARCHAR(500),
  syllabus_file_id VARCHAR(100),
  is_active TINYINT(1) DEFAULT 1,
  INDEX idx_code (code)
) ENGINE=InnoDB;

-- 9. Topik Riset Utama (Research Topics)
CREATE TABLE IF NOT EXISTS research_topics (
  id VARCHAR(64) PRIMARY KEY,
  title VARCHAR(255) NOT NULL,
  description TEXT,
  key_concepts TEXT
) ENGINE=InnoDB;

-- 10. Proyek Riset & Hibah (Research Projects)
CREATE TABLE IF NOT EXISTS research_projects (
  id VARCHAR(64) PRIMARY KEY,
  title TEXT NOT NULL,
  topic_id VARCHAR(64),
  period VARCHAR(50) NOT NULL,
  funding_source VARCHAR(200),
  grant_name VARCHAR(255),
  role VARCHAR(100) NOT NULL,
  collaborators TEXT,
  description TEXT,
  status VARCHAR(50) NOT NULL
) ENGINE=InnoDB;

-- 11. Dewan Editor Jurnal (Editorial Roles)
CREATE TABLE IF NOT EXISTS editorial_roles (
  id VARCHAR(64) PRIMARY KEY,
  role VARCHAR(150) NOT NULL,
  venue VARCHAR(255) NOT NULL,
  publisher VARCHAR(255),
  indexing VARCHAR(150),
  period VARCHAR(50) NOT NULL,
  url VARCHAR(500),
  description TEXT
) ENGINE=InnoDB;

-- 12. Liputan Pers & Media (Press & Media)
CREATE TABLE IF NOT EXISTS press_media (
  id VARCHAR(64) PRIMARY KEY,
  title TEXT NOT NULL,
  media_outlet VARCHAR(200) NOT NULL,
  publish_date VARCHAR(50) NOT NULL,
  category VARCHAR(50) NOT NULL,
  url VARCHAR(500),
  summary TEXT,
  image_url VARCHAR(500)
) ENGINE=InnoDB;

-- 13. Catatan & Artikel Blog (Blog Posts)
CREATE TABLE IF NOT EXISTS blog_posts (
  id VARCHAR(64) PRIMARY KEY,
  title TEXT NOT NULL,
  slug VARCHAR(255) NOT NULL UNIQUE,
  published_at VARCHAR(50) NOT NULL,
  read_time VARCHAR(50),
  tags TEXT,
  excerpt TEXT,
  content LONGTEXT NOT NULL,
  status VARCHAR(30) NOT NULL,
  author VARCHAR(150) NOT NULL,
  category VARCHAR(100)
) ENGINE=InnoDB;

-- 14. Profil Akademik Dosen (Academic Profile)
CREATE TABLE IF NOT EXISTS academic_profile (
  id VARCHAR(64) PRIMARY KEY,
  name VARCHAR(150) NOT NULL,
  title_with_degrees VARCHAR(200) NOT NULL,
  role VARCHAR(150) NOT NULL,
  department VARCHAR(150),
  faculty VARCHAR(150),
  institution VARCHAR(200),
  location VARCHAR(150),
  email VARCHAR(150) NOT NULL,
  program_studi VARCHAR(150),
  office VARCHAR(150),
  bio TEXT,
  bio_short TEXT,
  research_interests TEXT,
  google_scholar_url VARCHAR(500),
  scopus_url VARCHAR(500),
  orcid_url VARCHAR(500),
  sinta_url VARCHAR(500),
  linkedin_url VARCHAR(500),
  research_gate_url VARCHAR(500),
  consultation_hours VARCHAR(200),
  lab_location VARCHAR(200),
  photo_url VARCHAR(500),
  photo_base64 LONGTEXT,
  cv_pdf_url VARCHAR(500),
  cv_pdf_file_name VARCHAR(200),
  education TEXT,
  work_history TEXT,
  appointments TEXT,
  awards TEXT,
  memberships TEXT,
  research_groups TEXT,
  updated_at VARCHAR(50)
) ENGINE=InnoDB;

-- 15. Akun Administrator Sistem (Admin Accounts)
CREATE TABLE IF NOT EXISTS admin_accounts (
  id VARCHAR(64) PRIMARY KEY,
  email VARCHAR(150) NOT NULL UNIQUE,
  nama_lengkap VARCHAR(150) NOT NULL,
  role VARCHAR(100) NOT NULL,
  password_hash VARCHAR(255) NOT NULL,
  salt VARCHAR(100) NOT NULL,
  created_at VARCHAR(50) NOT NULL
) ENGINE=InnoDB;

