-- teaching_courses: 5 baris
INSERT INTO teaching_courses (id, code, name, level, program, academic_year, semester, description, learning_outcomes, materials_url, syllabus_file_id, is_active) VALUES
('tch-3', 'DTA204', 'Sains Data & Optimasi', 'Undergraduate (S1)', 'S1 Sains Data', '2024/2025', 'Ganjil', 'Integrasi metode pemelajaran mesin terapan (machine learning) dengan teknik optimasi matematis dan pengambilan keputusan.', 'Menguasai algoritma optimasi berbasis gradien|Mampu menerapkan feature selection dan dimensional reduction|Mampu membangun pipeline prediksi berbasis data empiris', 'https://spada.uns.ac.id', NULL, 1),
('tch-5', 'MAT205', 'Aljabar Linear Elementer', 'Undergraduate (S1)', 'S1 Matematika', '2024/2025', 'Ganjil', 'Konsep dasar ruang vektor, transformasi linear, nilai eigen, dan dekomposisi matriks untuk komputasi sains.', 'Memahami konsep ruang vektor Euclides dan umum|Mampu menghitung nilai dan vektor eigen matriks|Menerapkan diagonalisasi matriks pada sistem dinamik', 'https://spada.uns.ac.id', NULL, 1),
('tch-1', 'MAT312', 'Pemodelan Matematika', 'Undergraduate (S1)', 'S1 Matematika', '2024/2025', 'Ganjil', 'Mata kuliah wajib keahlian yang mempelajari formulasi matematis untuk fenomena fisis, biologis, dan sistem operasional industri.', 'Mampu merumuskan masalah nyata ke dalam model diferensial dan diskret|Mampu melakukan analisis sensitivitas dan stabilitas solusi model|Mampu memvalidasi hasil simulasi komputasi dengan data empiris', 'https://spada.uns.ac.id', NULL, 1),
('tch-2', 'MAT421', 'Riset Operasi Lanjut', 'Undergraduate (S1)', 'S1 Matematika', '2024/2025', 'Genap', 'Pendalaman algoritma optimasi kombinatorial, Vehicle Routing Problem (VRP), dynamic programming, dan teori antrian.', 'Mampu memformulasikan Mixed Integer Linear Programming (MILP)|Mampu menerapkan algoritma metaheuristik (Genetic Algorithm, Simulated Annealing)|Mampu menyelesaikan persoalan rute logistik skala besar', 'https://spada.uns.ac.id', NULL, 1),
('tch-4', 'MAT501', 'Pemodelan Optimasi Lanjut', 'Graduate (S2)', 'S2 Matematika', '2024/2025', 'Ganjil', 'Studi pascasarjana tentang closed-loop supply chain, formulasi non-linear, discrete choice experiments, dan game theory.', 'Mampu merancang model matematika interaksi multi-echelon supply chain|Menguasai metode penaksiran probabilitas pilihan diskret|Mampu mempublikasikan artikel riset optimasi pada jurnal bereputasi', 'https://spada.uns.ac.id', NULL, 1);

-- research_topics: 3 baris
INSERT INTO research_topics (id, title, description, key_concepts) VALUES
('top-1', 'Closed-Loop Supply Chain & Circular Economy', 'Pengembangan model optimasi rantai pasok tertutup yang mengintegrasikan logistik maju (forward logistics) dan logistik balik (reverse logistics) guna mendukung keberlanjutan lingkungan dan ekonomi sirkular.', 'Remanufacturing & Refurbishing|Carbon Cap-and-Trade Policy|Game Theoretic Coordination|Consumer Green Behavior'),
('top-2', 'Electric Vehicle Routing Problem (EVRP) with Energy & Time Window Constraints', 'Perancangan formulasi Mixed-Integer Linear Programming (MILP) dan algoritma metaheuristik hibrida untuk penentuan rute optimal armada kendaraan listrik dengan kendala pengisian baterai dan jendela waktu pengiriman.', 'Fleet Routing Optimization|Dynamic Battery Consumption|Fast Charging Station Allocation|Hybrid Genetic & Neighborhood Search'),
('top-3', 'Explainable Artificial Intelligence (XAI) in Operational Decision-Making', 'Penerapan kerangka kerja kecerdasan buatan terjelaskan (SHAP, LIME, Counterfactual Explanations) pada model prediksi dan sistem pendukung keputusan operasional kesehatan dan perbankan.', 'Shapley Additive Explanations|Model Transparency & Accountability|Fairness in Algorithmic Decisions|Operational Risk Modeling');

