INSERT INTO research_projects (id, title, topic_id, period, funding_source, grant_name, role, collaborators, description, status) VALUES
('prj-1', 'Optimasi Rute Armada Kendaraan Listrik (EVRP) dengan Stasiun Pengisian Cepat dan Kendala Baterai Dinamis', 'top-2', '2023 – 2025', 'Kemdiktisaintek RI', 'Penelitian Terapan Unggulan Perguruan Tinggi (PTUPT)', 'Ketua Peneliti', 'Dosen Jurusan Matematika FMIPA UNS|Mahasiswa S1/S2 Matematika', 'Mengembangkan model komputasi matematis untuk menyelesaikan permasalahan rute distribusi logistik perkotaan menggunakan kendaraan listrik dengan mempertimbangkan degradasi baterai dan waktu tunggu pengisian daya.', 'Ongoing'),
('prj-2', 'Pengembangan Kerangka Kerja Explainable Artificial Intelligence (XAI) untuk Sistem Keputusan Industri dan Kesehatan', 'top-3', '2022 – 2024', 'LPPM Universitas Sebelas Maret (UNS)', 'Hibah Riset Kolaborasi UNS', 'Ketua Peneliti', 'Dosen Department of Mathematics FMIPA UNS', 'Mengintegrasikan teknik XAI (SHAP, LIME, GANs) untuk memastikan transparansi dan akuntabilitas model cerdas buatan pada sistem pendukung keputusan klinis dan penilaian risiko kredit.', 'Completed');

