-- academic_profile: 1 baris
INSERT INTO academic_profile (id, name, title_with_degrees, role, department, faculty, institution, location, email, program_studi, office, bio, bio_short, research_interests, google_scholar_url, scopus_url, orcid_url, sinta_url, linkedin_url, research_gate_url, consultation_hours, lab_location, photo_url, photo_base64, cv_pdf_url, cv_pdf_file_name, education, work_history, appointments, awards, memberships, research_groups, updated_at) VALUES
('profile-kurdhi', 'Nughthoh Arfawi Kurdhi, S.Si., M.Sc., Ph.D.', 'Nughthoh Arfawi Kurdhi, S.Si., M.Sc., Ph.D.', 'Associate Professor & Head of Applied Mathematics Research Group', 'Department of Mathematics', 'Faculty of Mathematics and Natural Sciences (FMIPA)', 'Universitas Sebelas Maret (UNS)', 'Surakarta, Central Java, Indonesia', 'arfa@staff.uns.ac.id', 'S1 Matematika & S1 Sains Data', 'Gedung A FMIPA UNS, Kampus Kentingan, Surakarta', 'Nughthoh Arfawi Kurdhi, S.Si., M.Sc., Ph.D. adalah Associate Professor dan Dosen Peneliti di Jurusan Matematika, Fakultas Matematika dan Ilmu Pengetahuan Alam (FMIPA), Universitas Sebelas Maret (UNS), Surakarta. Menyelesaikan pendidikan Doktor (Ph.D.) di Department of Industrial Engineering and Innovation Sciences, Eindhoven University of Technology (TU/e), Belanda dengan kepakaran khusus pada Optimization, Operations Research, Closed-Loop Supply Chain, and Discrete Choice Experiments.

Aktif memimpin Riset Kolaborasi Internasional dan Nasional dalam pengembangan model matematis dan metaheuristik untuk permasalahan berskala besar, termasuk Electric Vehicle Routing Problem (EVRP), Explainable Artificial Intelligence (XAI), Generative AI, serta Pemodelan Matematika Sistem Epidemiologi.', 'Associate Professor & Dosen Peneliti di Departemen Matematika FMIPA Universitas Sebelas Maret (UNS). Menggeluti Riset Operasi, Optimasi Kombinatorial, Closed-Loop Supply Chain, dan Discrete Choice Experiments.', 'Operations Research and Optimization, Closed-Loop Supply Chain & Circular Economy, Discrete Choice Experiments, Mathematical Modelling, Data Science and Scientific Machine Learning, Explainable Artificial Intelligence (XAI), Electric Vehicle Routing Problem (EVRP)', 'https://scholar.google.com/citations?user=W2lGnqIAAAAJ', 'https://www.scopus.com/authid/detail.uri?authorId=55851190200', 'https://orcid.org/0000-0001-9274-1807', 'https://sinta.kemdiktisaintek.go.id/authors/profile/6765487/?view=iprs', 'https://linkedin.com', 'https://researchgate.net', 'Senin & Jumat 08:00 - 15:00 WIB', 'Laboratorium Komputasi dan Optimasi Matematika, FMIPA UNS', '/nughthoh_photo.webp', NULL, 'https://expert.uns.ac.id/researcher/1091?export=cv', 'CV_Nughthoh_Arfawi_Kurdhi_UNS.pdf', '[{"id":"edu-1","degree":"Ph.D. in Applied Mathematics (Industrial Engineering)","institution":"Eindhoven University of Technology, Netherlands","year":"2021","field":"Applied Mathematics & Industrial Engineering","thesisTitle":"Optimization and Discrete Choice Experiments in Industrial & Health Operations"},{"id":"edu-2","degree":"M.Sc. in Applied Mathematics","institution":"Universitas Gadjah Mada (UGM), Indonesia","year":"2010","field":"Applied Mathematics"},{"id":"edu-3","degree":"B.Sc. in Mathematics (S.Si.)","institution":"Universitas Sebelas Maret (UNS), Indonesia","year":"2010","field":"Mathematics"}]', '[{"id":"work-1","period":"2022","role":"Visiting Researcher","institution":"Department of Management, Tilburg University, Netherlands","description":"Research in operational management, discrete choice models, and healthcare systems optimization."},{"id":"work-2","period":"2022–2024","role":"University Researcher","institution":"Eindhoven University of Technology, Netherlands","description":"Postdoctoral research in operations research, mathematical modelling, and discrete choice experiments."}]', '[{"id":"app-1","role":"Faculty Lecturer & Senior Researcher","department":"Department of Mathematics","institution":"FMIPA, Universitas Sebelas Maret (UNS)","period":"2010 – Present","description":"Teaching undergraduate, master, and doctoral students, and directing applied mathematics research."},{"id":"app-2","role":"Head of Research Group","department":"Mathematical Modelling, Data Science, and Scientific Machine Learning","institution":"Universitas Sebelas Maret","period":"2016 – Present","description":"Directing multidisciplinary research in applied mathematics, data science, scientific ML, and XAI."}]', '[{"id":"awd-1","title":"Publication in Premier Journal (ABS 4*)","organization":"Journal of Operations Management","year":2023,"description":"High-impact scientific research published in a premier world-leading operations research journal."},{"id":"awd-2","title":"National & International Competitive Research Grants","organization":"Ministry of Higher Education, Science and Technology RI","year":2022,"description":"Competitive grant awards for mathematical modelling and Electric Vehicle Routing Problem (EVRP)."}]', '["Indonesian Mathematical Society (IndoMS)","Operations Research Society of Indonesia (ORSI)","Association of European Operational Research Societies (EURO)"]', '[{"id":"rg-active","code":"M12144414","name":"Mathematical Modelling, Data Science, and Scientific Machine Learning","period":"2016–Present","isActive":true},{"id":"rg-hist-1","code":"M24085259","name":"Operations Research and Optimization","period":"2014–2018","isActive":false},{"id":"rg-hist-2","code":"M24085214","name":"Mathematical Modelling and Optimization","period":"2018–2018","isActive":false},{"id":"rg-hist-3","code":"M08092340","name":"Mathematical Modelling and Optimization","period":"2018–2019","isActive":false},{"id":"rg-hist-4","code":"X17204958","name":"Biomechanics and Sports Technology","period":"2023–2026","isActive":false}]', '2026-10-26T15:52:40.654Z');

