-- --------------------------------------------------------
-- Table structure for table `student_research` (13 Active Supervised Research Students)
-- --------------------------------------------------------
CREATE TABLE IF NOT EXISTS `student_research` (
  `id` int NOT NULL AUTO_INCREMENT,
  `nama` varchar(255) NOT NULL,
  `nim` varchar(50) NOT NULL,
  `judul_proposal` text NOT NULL,
  `research_topic` text,
  `doc_id` int DEFAULT NULL,
  `detail_url` varchar(500) DEFAULT NULL,
  `status` varchar(50) DEFAULT "active",
  `photo_url` varchar(500) DEFAULT NULL,
  `photo_base64` longtext,
  `infographic` longtext,
  `has_infographic` tinyint(1) DEFAULT 0,
  `pembimbing` text,
  `penguji` text,
  `tahun` smallint unsigned DEFAULT 2024,
  `program_studi` varchar(100) DEFAULT "Matematika",
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

